/**
 * Data-at-rest format of packages/providers/src/fixtures/accounts.json, generated by scripts/gen-claims-fixture.py
 * from the handoff reference model (ADR-0008). Not part of types.ts: providers turn it into `Position`/`ClaimView`.
 *
 * Guards: every ledger names a feed pair with the same reward side; the replay reconciles with the feed record
 * (fee-burned T, total supply, eligible supply = circulating); per-account sums equal the ledger totals; and the
 * exact identity  holderAllocated = deferred + claimable + claimed + roundingDust  holds with
 * 0 <= roundingDust < accounts + settled claims  (floor rounding never overstates a claim; ECO-03, ECO-15).
 */
import { z } from 'zod';
import { isRawAmount } from './amounts';
import type { GuardIssue, IssuePath } from './guards';
import { canonicalPairId, isAddress, isPairId, sameAddress } from './ids';
import type { FeedFixture } from './schemas';
import type { Address, PairId } from './types';
import {
  addressField,
  chainIdField,
  decimalAmountField,
  isRecord,
  isoTimestampField,
  pairIdField,
  parseWith,
  rawAmountField,
  reportIssues,
  textField,
} from './validation';

const RATIONAL = /^(0|[1-9][0-9]*)(\/[1-9][0-9]*)?$/;
const rationalField = z.string().regex(RATIONAL, 'must be an exact non-negative rational "n" or "n/d"');
const sha256Field = z.string().regex(/^[0-9a-f]{64}$/, 'must be a lowercase sha256 hex digest');

/** Exact non-negative rational from "n" or "n/d". */
export function parseRational(value: string): { num: bigint; den: bigint } {
  const match = RATIONAL.exec(value);
  if (!match) throw new RangeError('expected "n" or "n/d"');
  const [, num = '0', den] = match;
  return { num: BigInt(num), den: den ? BigInt(den.slice(1)) : 1n };
}

const historyEntry = z.strictObject({
  at: isoTimestampField,
  block: rawAmountField,
  qConsumedRaw: rawAmountField,
  payoutRaw: rawAmountField,
  payoutSide: z.enum(['Q', 'T']),
  outcome: z.enum(['settled', 'reverted']),
  reason: z.string().min(1).max(120).optional(),
});

const ledgerEvent = z.strictObject({
  step: z.number().int().min(1),
  at: isoTimestampField,
  block: rawAmountField,
  kind: z.enum(['buy', 'sell', 'claim_q', 'claim_t', 'claim_t_revert', 'pending_harvest']),
  account: addressField.optional(),
  receiptId: z.string().min(1).max(64).optional(),
  tRaw: rawAmountField.optional(),
  feeQRaw: rawAmountField.optional(),
  feeTRaw: rawAmountField.optional(),
  qConsumedRaw: rawAmountField.optional(),
  payoutRaw: rawAmountField.optional(),
  payoutSide: z.enum(['Q', 'T']).optional(),
  tPerQ: decimalAmountField.optional(),
  executableTPerQ: decimalAmountField.optional(),
  minPayoutRaw: rawAmountField.optional(),
  offeredPayoutRaw: rawAmountField.optional(),
  outcome: z.literal('reverted').optional(),
  recognised: z.literal(false).optional(),
});

const ledgerAccount = z.strictObject({
  address: addressField,
  role: z.enum(['persona', 'demo_holder']),
  persona: z.string().min(1).nullable(),
  balanceRaw: rawAmountField,
  nftTokenIds: z.array(rawAmountField),
  claimableQRaw: rawAmountField,
  claimableRemainderQ: rationalField,
  claimedQRaw: rawAmountField,
  pendingHarvestQRaw: rawAmountField,
  history: z.array(historyEntry),
  convertibleEstimate: z.strictObject({ payoutRaw: rawAmountField, minPayoutRaw: rawAmountField }).nullable(),
});

const ledgerShape = z.strictObject({
  pairId: pairIdField,
  slug: z.string().min(1),
  rewardSide: z.enum(['T', 'Q']),
  tDecimals: z.number().int().min(0).max(36),
  qDecimals: z.number().int().min(0).max(36),
  events: z.array(ledgerEvent),
  accounts: z.array(ledgerAccount),
  excluded: z.strictObject({ marketRaw: rawAmountField, feeCollectorRaw: rawAmountField }),
  quote: z
    .strictObject({
      source: z.literal('demo_quote'),
      tPerQ: decimalAmountField,
      quotedAt: isoTimestampField,
      asOfBlock: rawAmountField,
      deadline: isoTimestampField,
      toleranceBps: z.number().int().min(0).max(10_000),
    })
    .nullable(),
  totals: z.strictObject({
    qReceivedRaw: rawAmountField,
    protocolQRaw: rawAmountField,
    holderAllocatedQRaw: rawAmountField,
    deferredQRaw: rawAmountField,
    claimableQRaw: rawAmountField,
    claimedQRaw: rawAmountField,
    roundingDustQ: rationalField,
    settledClaims: z.number().int().min(0),
    tPaidRaw: rawAmountField,
    tBurnedRaw: rawAmountField,
    pendingHarvestQRaw: rawAmountField,
    eligibleSupplyRaw: rawAmountField,
    totalSupplyRaw: rawAmountField,
  }),
});

const accountsFixtureShape = z.strictObject({
  schemaVersion: z.literal('1.0'),
  mode: z.literal('demo'),
  chainId: chainIdField,
  asOf: isoTimestampField,
  asOfBlock: rawAmountField,
  blockClock: z.strictObject({ genesis: isoTimestampField, blockSeconds: z.number().int().min(1) }),
  note: z.string().min(1),
  generator: z.literal('scripts/gen-claims-fixture.py'),
  reference: z.literal('square-hole-handoff/reference/fee_policy_model.py'),
  referenceSha256: sha256Field,
  feedFixtureSha256: sha256Field,
  rounding: z.literal('floor'),
  claimToleranceBps: z.number().int().min(0).max(10_000),
  measuredPolicy: z.strictObject({ qProtocolShare: rationalField, qHolderShare: rationalField }),
  personas: z
    .array(
      z.strictObject({
        id: z.enum(['current_holder', 'past_holder', 'never_held']),
        label: textField({ min: 1, max: 64, innerSpaces: true, newlines: false }),
        address: addressField,
      }),
    )
    .min(1),
  ledgers: z.array(ledgerShape),
});

export type AccountsFixture = z.output<typeof accountsFixtureShape>;
export type AccountsLedger = AccountsFixture['ledgers'][number];
export type AccountsLedgerAccount = AccountsLedger['accounts'][number];
export type DemoPersonaId = AccountsFixture['personas'][number]['id'];
export interface DemoPersona {
  id: DemoPersonaId;
  label: string;
  address: Address;
}

const sum = (values: readonly unknown[]): bigint => values.reduce<bigint>((total, value) => total + (isRawAmount(value) ? BigInt(value) : 0n), 0n);

function ledgerIssues(ledger: AccountsLedger, feed: FeedFixture, base: IssuePath): GuardIssue[] {
  const issues: GuardIssue[] = [];
  const add = (path: IssuePath, message: string): void => {
    issues.push({ path: [...base, ...path], message });
  };
  const pair = isPairId(ledger.pairId) ? feed.items.find((item) => canonicalPairId(item.pairId) === canonicalPairId(ledger.pairId)) : undefined;
  if (!pair) {
    add(['pairId'], 'every ledger replays a pair in the feed fixture');
    return issues;
  }
  if (ledger.rewardSide !== pair.rewardSide) add(['rewardSide'], 'must equal the pair’s fee-share side (ECO-04)');
  if (ledger.tDecimals !== pair.token.decimals) add(['tDecimals'], 'must equal the pair token decimals');
  if (ledger.qDecimals !== pair.quote.decimals) add(['qDecimals'], 'must equal the pair quote decimals');
  if ((ledger.quote !== null) !== (pair.rewardSide === 'T')) add(['quote'], 'a conversion quote exists exactly for R=T pairs');
  const { totals } = ledger;
  if (totals.tBurnedRaw !== pair.burnedRaw) add(['totals', 'tBurnedRaw'], 'replayed burns must equal the feed burnedRaw (FEED-07)');
  if (totals.totalSupplyRaw !== pair.totalSupplyRaw) add(['totals', 'totalSupplyRaw'], 'replayed supply must equal the feed totalSupplyRaw');
  if (totals.eligibleSupplyRaw !== pair.circulatingSupplyRaw) add(['totals', 'eligibleSupplyRaw'], 'eligible supply must equal the feed circulating supply');

  const accounts = ledger.accounts;
  if (sum(accounts.map((account) => account.claimableQRaw)) !== BigInt(totals.claimableQRaw)) add(['totals', 'claimableQRaw'], 'must equal the per-account sum');
  if (sum(accounts.map((account) => account.claimedQRaw)) !== BigInt(totals.claimedQRaw)) add(['totals', 'claimedQRaw'], 'must equal the per-account sum');
  if (sum(accounts.map((account) => account.balanceRaw)) !== BigInt(totals.eligibleSupplyRaw)) {
    add(['accounts'], 'every eligible holder is listed: balances must sum to the eligible supply');
  }
  if (BigInt(totals.eligibleSupplyRaw) + BigInt(ledger.excluded.marketRaw) + BigInt(ledger.excluded.feeCollectorRaw) !== BigInt(totals.totalSupplyRaw)) {
    add(['excluded'], 'eligible + excluded balances must equal total supply');
  }
  const dust = parseRational(totals.roundingDustQ);
  const allocated = BigInt(totals.holderAllocatedQRaw);
  const explained = BigInt(totals.deferredQRaw) + BigInt(totals.claimableQRaw) + BigInt(totals.claimedQRaw);
  if (explained * dust.den + dust.num !== allocated * dust.den) {
    add(['totals', 'roundingDustQ'], 'holderAllocated must equal deferred + claimable + claimed + rounding dust exactly');
  }
  if (dust.num >= BigInt(accounts.length + totals.settledClaims) * dust.den) {
    add(['totals', 'roundingDustQ'], 'rounding dust must stay below one raw unit per account and settled claim (ECO-15)');
  }
  const seen = new Set<string>();
  accounts.forEach((account, index) => {
    const key = account.address.toLowerCase();
    if (seen.has(key)) add(['accounts', index, 'address'], 'duplicate account');
    seen.add(key);
    const settled = sum(account.history.filter((entry) => entry.outcome === 'settled').map((entry) => entry.qConsumedRaw));
    if (settled !== BigInt(account.claimedQRaw)) add(['accounts', index, 'claimedQRaw'], 'must equal the settled history');
    const remainder = parseRational(account.claimableRemainderQ);
    if (remainder.num >= remainder.den) add(['accounts', index, 'claimableRemainderQ'], 'a floor remainder is below one raw unit');
  });
  return issues;
}

/** Validates the generated accounts fixture against the feed fixture it was replayed from. */
export function parseAccountsFixture(input: unknown, feed: FeedFixture): AccountsFixture {
  const schema = accountsFixtureShape.superRefine((file, ctx) => {
    const add = (path: IssuePath, message: string): void => reportIssues(ctx, [{ path, message }]);
    if (file.chainId !== feed.chainId) add(['chainId'], 'must equal the feed chainId');
    if (file.asOf !== feed.asOf) add(['asOf'], 'must equal the feed asOf');
    const personaAddresses = new Set<string>();
    file.personas.forEach((persona, index) => {
      if (!isAddress(persona.address)) return;
      if (personaAddresses.has(persona.address.toLowerCase())) add(['personas', index, 'address'], 'duplicate persona address');
      personaAddresses.add(persona.address.toLowerCase());
      if (!/demo/i.test(persona.label)) add(['personas', index, 'label'], 'personas are labelled demo');
    });
    const ledgerIds = new Set<string>();
    file.ledgers.forEach((ledger, index) => {
      if (!isRecord(ledger) || !isPairId(ledger.pairId)) return;
      const key = canonicalPairId(ledger.pairId);
      if (ledgerIds.has(key)) add(['ledgers', index, 'pairId'], 'one ledger per pair');
      ledgerIds.add(key);
      reportIssues(ctx, ledgerIssues(ledger, feed, ['ledgers', index]));
      ledger.accounts.forEach((account, accountIndex) => {
        const persona = file.personas.find((candidate) => sameAddress(candidate.address, account.address));
        if ((account.role === 'persona') !== (persona !== undefined) || (persona && persona.id !== account.persona)) {
          add(['ledgers', index, 'accounts', accountIndex, 'persona'], 'persona accounts name their persona');
        }
      });
    });
  });
  return parseWith(schema, input, 'accounts fixture');
}

/** Ledger lookup by canonical pair id. */
export function ledgerFor(fixture: AccountsFixture, pairId: PairId): AccountsLedger | undefined {
  const key = canonicalPairId(pairId);
  return fixture.ledgers.find((ledger) => canonicalPairId(ledger.pairId) === key);
}
